function teacherUiLanguage(){const v=localStorage.getItem('isc-teacher-ui-language')||'english';return TEACHER_UI_LANGS[v]?v:'english'}
function teacherUiText(k){const d=TEACHER_UI_WORDS[teacherUiLanguage()]||TEACHER_UI_WORDS.english;return d[k]||TEACHER_UI_WORDS.english[k]||k}
function teacherFlagSwitcher(){const current=TEACHER_UI_LANGS[teacherUiLanguage()];return `<div class="teacher-flag-switch"><button type="button" id="teacherFlagButton" class="teacher-flag-button" aria-label="${esc(teacherUiText('language'))}" title="${esc(teacherUiText('language'))}"><span>${current.flag}</span><small>${esc(current.name)}</small><b>⌄</b></button><div id="teacherFlagMenu" class="teacher-flag-menu" hidden>${Object.entries(TEACHER_UI_LANGS).map(([k,v])=>`<button type="button" data-teacher-ui-lang="${k}" class="${k===teacherUiLanguage()?'active':''}"><span>${v.flag}</span><b>${esc(v.name)}</b></button>`).join('')}</div></div>`}
function bindTeacherFlagSwitcher(tab){const btn=$('#teacherFlagButton'),menu=$('#teacherFlagMenu');if(!btn||!menu)return;btn.onclick=e=>{e.stopPropagation();menu.hidden=!menu.hidden};$$('[data-teacher-ui-lang]',menu).forEach(x=>x.onclick=()=>{localStorage.setItem('isc-teacher-ui-language',x.dataset.teacherUiLang);openApprovedTeacherDashboard(tab)});setTimeout(()=>document.addEventListener('click',()=>{if(menu)menu.hidden=true},{once:true}),0)}
function applyTeacherUiLanguage(root=document){const d=TEACHER_UI_WORDS[teacherUiLanguage()]||TEACHER_UI_WORDS.english;const tabKey={overview:'dashboard',calendar:'calendar',schedule:'availability',classroom:'classroom',lessons:'lessons',students:'students',messages:'messages',academy:'academy',pricing:'rate',profile:'profile',admin:'admin'};root.querySelectorAll('[data-portal-tab]').forEach(b=>{const k=tabKey[b.dataset.portalTab];if(k&&d[k])b.textContent=d[k]});const pw=root.querySelector('#teacherPortalPassword');if(pw)pw.textContent=d.password;const lo=root.querySelector('#teacherPortalLogout');if(lo)lo.textContent=d.logout;root.dir=teacherUiLanguage()==='arabic'?'rtl':'ltr'}
