// Privacy-respecting product analytics: no raw IP address is stored.
const ISPEAK_ANALYTICS_SESSION=(()=>{let v=sessionStorage.getItem('ispeak_analytics_session');if(!v){v=(crypto.randomUUID?.()||('s-'+Date.now()+'-'+Math.random().toString(16).slice(2)));sessionStorage.setItem('ispeak_analytics_session',v)}return v})();
function analyticsDevice(){return matchMedia('(max-width: 700px)').matches?'mobile':matchMedia('(max-width: 1100px)').matches?'tablet':'desktop'}
function trackAnalytics(type,extra={}){const body={type,session:ISPEAK_ANALYTICS_SESSION,page:document.querySelector('.view.active,.page.active')?.id||location.pathname,language:state?.language||'',uiLanguage:state?.uiLanguage||'',device:analyticsDevice(),source:new URLSearchParams(location.search).get('utm_source')||document.referrer?.split('/')[2]||'direct',...extra};fetch('/api/analytics/event',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),keepalive:true}).catch(()=>{})}
setTimeout(()=>trackAnalytics('session_start'),1200);
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;const target=(b.dataset?.teacher?`teacher:${b.dataset.teacher}`:b.dataset?.view?`nav:${b.dataset.view}`:b.id||b.textContent||b.getAttribute('aria-label')||'control').trim().slice(0,120);trackAnalytics('click',{target});if(b.classList.contains('book-btn'))trackAnalytics('booking_start',{target:b.dataset.teacher||''});if(b.classList.contains('profile-btn'))trackAnalytics('teacher_view',{target:b.dataset.profile||''})},{passive:true});
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const courseOrderSafe=()=>['khmer','english','mandarin','spanish','french','japanese','arabic'];
const defaults={schemaVersion:1800,language:'khmer',xp:0,streak:0,completed:[],attempts:0,correct:0,dailyGoal:3,lastDay:'',activity:{},name:'Student',bookings:[],mascot:'jess',voice:true,roomMode:'talk',coins:20,mood:92,energy:88,ownedAccessories:['none'],accessory:'none',placement:{},studyCompleted:[],studyMinutes:0,email:'',certificates:{},unitMastery:{},placementDetail:{},uiLanguage:'english',onboardingDone:false,onboardingVersion:0,learningPlan:{reason:'Conversation',minutes:15,targetDate:'',targetLevel:'Beginner'},quests:{},missionProgress:{},pronunciationHistory:[],account:null,cloudSyncAt:null,khmerNativeSeen:[],libraryNotes:{},skillEvidence:{},errorHistory:[],learnerModel:{},translationFallbacks:{},heroReadingProgress:{},ieltsProgress:{}};
const validMascots=['jess','jack','pedro','loulou','yuki','dariya','zayd'];
let loadedState={};
try{loadedState=JSON.parse(localStorage.getItem('isc-v17-5-0')||localStorage.getItem('isc-v17-3-0')||localStorage.getItem('isc-v17-2-1')||localStorage.getItem('isc-v17-2-0')||localStorage.getItem('isc-v16-0-6')||localStorage.getItem('isc-v15')||localStorage.getItem('isc-v13-4')||localStorage.getItem('isc-v9')||'{}')}catch{}
if(!validMascots.includes(loadedState.mascot))loadedState.mascot='jess';
const state=Object.assign({},defaults,loadedState);
function normalizeState(){
 if(!courseOrderSafe().includes(state.language))state.language='khmer';
 if(!courseOrderSafe().includes(state.uiLanguage))state.uiLanguage='english';
 if(!validMascots.includes(state.mascot))state.mascot='jess';
 for(const k of ['completed','bookings','studyCompleted','pronunciationHistory','khmerNativeSeen','errorHistory'])if(!Array.isArray(state[k]))state[k]=[];
 if(!state.skillEvidence||typeof state.skillEvidence!=='object')state.skillEvidence={};
 if(!state.learnerModel||typeof state.learnerModel!=='object')state.learnerModel={};
 if(!state.translationFallbacks||typeof state.translationFallbacks!=='object')state.translationFallbacks={};
 state.schemaVersion=1800;
 for(const k of ['activity','placement','certificates','unitMastery','placementDetail','learningPlan','quests','missionProgress','writingMastery','libraryNotes','heroReadingProgress','ieltsProgress'])if(!state[k]||typeof state[k]!=='object'||Array.isArray(state[k]))state[k]={};
 state.dailyGoal=[1,3,5].includes(Number(state.dailyGoal))?Number(state.dailyGoal):3;
 state.xp=Math.max(0,Number(state.xp)||0);state.coins=Math.max(0,Number(state.coins)||0);state.streak=Math.max(0,Number(state.streak)||0);
}
normalizeState();
let __cloudTimer=null;
const localSave=()=>{state.schemaVersion=1750;localStorage.setItem('isc-v17-5-0',JSON.stringify(state));};
const save=()=>{localSave();render();if(state.account?.token){clearTimeout(__cloudTimer);__cloudTimer=setTimeout(()=>cloudSave().catch(()=>{}),900)}};
async function apiJSON(path,opts={}){const h={'Content-Type':'application/json',...(opts.headers||{})};if(state.account?.token&&!h.Authorization)h.Authorization='Bearer '+state.account.token;const r=await fetch(path,{...opts,headers:h});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||'Request failed');return d}
async function cloudSave(){if(!state.account?.token)return;const copy=JSON.parse(JSON.stringify(state));delete copy.account;const d=await apiJSON('/api/account/progress',{method:'PUT',body:JSON.stringify({state:copy})});state.cloudSyncAt=d.updatedAt||new Date().toISOString();localSave()}
async function cloudLoad(){if(!state.account?.token)return;const d=await apiJSON('/api/account/progress');if(d.state&&typeof d.state==='object'){const account=state.account;Object.assign(state,d.state);state.account=account;state.cloudSyncAt=d.updatedAt||null;normalizeState();syncBuddyWithLearningLanguage({clearConversation:true});localSave();render()}}

