 if(!w)return toast('Please allow pop-ups to print your certificate.');
 w.document.write(`<!doctype html><html><head><title>${certificateDisplayCourseName(lang)} — ${certUI().certificate}</title><link rel="stylesheet" href="${location.origin}/styles.css"></head><body class="certificate-print-page">${certificateHTML(lang,true)}</body></html>`);
