const APP_UI_ALIASES={
 '📚 Library':'Library','✍️ Writing Academy':'Writing Academy','✨ Connect Gemini AI':'Connect Gemini AI','▶ Watch introduction':'Watch introduction','☁️ Account & Cloud Sync':'Account & Cloud Sync','🧭 My Learning Plan':'My Learning Plan','🏆 Daily Quests':'Daily Quests','🌍 Real-Life Missions':'Real-Life Missions','⬇️ Offline Learning':'Offline Learning','🌐 Learning language':'Learning language','🎯 Daily goal':'Daily goal','🎙️ Audio & microphone check':'Audio & microphone check','📅 My lesson requests':'My lesson requests','🔐 Privacy, Safety & Terms':'Privacy, Safety & Terms'
};
function appTr(s){const d=APP_UI_TEXT[state.uiLanguage]||{},x=APP_UI_TEXT_EXTRA[state.uiLanguage]||{};const alias=APP_UI_ALIASES[s];if(alias){const core=x[alias]||d[alias]||(UI_TEXT[state.uiLanguage]||{})[alias]||alias;const prefix=s.slice(0,s.indexOf(alias));return prefix+core}return x[s]||d[s]||(UI_TEXT[state.uiLanguage]||{})[s]||s}
function localizedCourseName(k){const l=languages[k];return appTr(l?.name||k)}
const l10nTextBases=new WeakMap();
function hasInterfaceTranslation(raw){return !!(raw&&(UI_TEXT.english[raw]||APP_UI_ALIASES[raw]||Object.values(APP_UI_TEXT).some(x=>Object.prototype.hasOwnProperty.call(x,raw))||Object.values(APP_UI_TEXT_EXTRA).some(x=>Object.prototype.hasOwnProperty.call(x,raw))))}
function localizeDocument(root=document){
 const host=root===document?document.body:root;if(!host)return;
 const walker=document.createTreeWalker(host,NodeFilter.SHOW_TEXT);let node;
 while((node=walker.nextNode())){
   const parent=node.parentElement;if(!parent||parent.closest('script,style,textarea,canvas'))continue;
   const current=node.nodeValue||'',trim=current.trim();let base=l10nTextBases.get(node);
   if(!base&&hasInterfaceTranslation(trim)){base=trim;l10nTextBases.set(node,base)}
   if(base){const translated=appTr(base),lead=current.match(/^\s*/)?.[0]||'',tail=current.match(/\s*$/)?.[0]||'',next=lead+translated+tail;if(node.nodeValue!==next)node.nodeValue=next;}
 }
 const elements=[host,...host.querySelectorAll?.('*')||[]];
 elements.forEach(el=>{
   if(!el?.getAttribute||el.matches('script,style,textarea,canvas'))return;
   ['title','placeholder','aria-label'].forEach(a=>{const cur=el.getAttribute(a);if(!cur)return;const prop='l10n'+a.replace(/-([a-z])/g,(_,c)=>c.toUpperCase());let base=el.dataset[prop];if(!base&&hasInterfaceTranslation(cur)){base=cur;el.dataset[prop]=base}if(base){const next=appTr(base);if(el.getAttribute(a)!==next)el.setAttribute(a,next);}});
 });
 // Dynamic course-card chrome: target/native language stays intact, labels follow interface language.
 document.querySelectorAll('.language-card[data-lang]').forEach(card=>{const k=card.dataset.lang,b=card.querySelector('b'),em=card.querySelector('em');if(b){const next=localizedCourseName(k);if(b.textContent!==next)b.textContent=next;}if(em){const done=studyDone(k),next=`${done}/${totalStudySessions} ${appTr('sessions')} • ${Math.round(done/8)} ${appTr('study days')}`;if(em.textContent!==next)em.textContent=next;}});
 const topLogin=$('#topLogin'),topSignup=$('#topSignup'),topAccount=$('#topAccount');if(topLogin){const next=appTr('Log In');if(topLogin.textContent!==next)topLogin.textContent=next;}if(topSignup){const next=appTr('Sign Up');if(topSignup.textContent!==next)topSignup.textContent=next;}if(topAccount){const next=appTr('My Account');if(topAccount.textContent!==next)topAccount.textContent=next;}
}
let localizationObserver=null;
function startLocalizationObserver(){if(localizationObserver)return;localizationObserver=new MutationObserver(ms=>{for(const m of ms){if(m.type==='characterData'&&m.target.parentElement)localizeDocument(m.target.parentElement);for(const n of m.addedNodes){if(n.nodeType===1)localizeDocument(n);else if(n.nodeType===3&&n.parentElement)localizeDocument(n.parentElement)}}});localizationObserver.observe(document.body,{childList:true,subtree:true,characterData:true});}

function tr(s){const d=UI_TEXT[state.uiLanguage]||UI_TEXT.english;return d[s]||appTr(s)||s}
function applyInterfaceLanguage(){
 const cfg=UI_LANGS[state.uiLanguage]||UI_LANGS.english;
 document.documentElement.lang=state.uiLanguage==='mandarin'?'zh':state.uiLanguage==='japanese'?'ja':state.uiLanguage==='arabic'?'ar':state.uiLanguage==='khmer'?'km':state.uiLanguage==='spanish'?'es':state.uiLanguage==='french'?'fr':'en';
 document.documentElement.dir=cfg.dir;
 document.body.classList.toggle('rtl-ui',cfg.dir==='rtl');
 const selectors=['.bottom-nav span','#drawer button','.hero-actions button','.hero-card .eyebrow','.section-head .eyebrow','.section-head h2','#learn .title .eyebrow','#learn .title h1','#practice .title h1','.practice-grid b','#progress .title .eyebrow','#progress .title h1','#progress .progress-card>h2','#profile .settings button','.room-nav b','.chathead b','#aiConnect'];
 document.querySelectorAll(selectors.join(',')).forEach(el=>{const base=el.dataset.i18nBase||el.textContent.trim();if(!el.dataset.i18nBase)el.dataset.i18nBase=base;el.textContent=tr(base)});
 localizeDocument();startLocalizationObserver();
}

