function renderBookingDays(data,preferredDate='',preferredTime=''){
 bookingAvailability=(data.days||[]).map(d=>({...d,timezone:data.timezone||'Asia/Phnom_Penh'}));
 const today=new Date();today.setHours(0,0,0,0);
 const preferred=preferredDate?new Date(preferredDate+'T12:00:00'):null;
 const firstOpen=bookingAvailability.find(x=>x.slots.length);
 bookingMonthCursor=preferred&&!Number.isNaN(preferred.getTime())?new Date(preferred.getFullYear(),preferred.getMonth(),1):new Date(today.getFullYear(),today.getMonth(),1);
 const renderMonth=()=>{
  const wrap=$('#bookingDays');if(!wrap)return;
  const y=bookingMonthCursor.getFullYear(),m=bookingMonthCursor.getMonth(),first=new Date(y,m,1),last=new Date(y,m+1,0),lead=(first.getDay()+6)%7;
  const monthLabel=first.toLocaleDateString([],{month:'long',year:'numeric'});
  const dayMap=new Map(bookingAvailability.map(d=>[d.date,d]));
  const cells=[];
  for(let i=0;i<lead;i++)cells.push('<span class="booking-calendar-blank" aria-hidden="true"></span>');
  for(let day=1;day<=last.getDate();day++){
   const key=`${y}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,row=dayMap.get(key),open=!!row?.slots?.length,dt=new Date(y,m,day),past=dt<today;
   const selected=$('#bookDate')?.value===key||(!$('#bookDate')?.value&&preferredDate===key);
   cells.push(`<button type="button" class="booking-calendar-day ${open?'has-times':''} ${selected?'active':''}" data-book-day="${key}" ${(!open||past)?'disabled':''}><span>${day}</span>${open?`<small>${row.slots.length} time${row.slots.length===1?'':'s'}</small>`:'<small>—</small>'}</button>`)
  }
  wrap.innerHTML=`<div class="booking-calendar-head"><button type="button" id="bookingPrevMonth" class="secondary" aria-label="Previous month">‹</button><div><b>${esc(monthLabel)}</b><small>Select an available date</small></div><button type="button" id="bookingNextMonth" class="secondary" aria-label="Next month">›</button></div><div class="booking-calendar-week"><b>Mon</b><b>Tue</b><b>Wed</b><b>Thu</b><b>Fri</b><b>Sat</b><b>Sun</b></div><div class="booking-calendar-grid">${cells.join('')}</div>`;
  $('#bookingPrevMonth').onclick=()=>{bookingMonthCursor=new Date(y,m-1,1);renderMonth()};
  $('#bookingNextMonth').onclick=()=>{bookingMonthCursor=new Date(y,m+1,1);renderMonth()};
  $$('[data-book-day]',wrap).forEach(b=>b.onclick=()=>{$$('[data-book-day]',wrap).forEach(x=>x.classList.remove('active'));b.classList.add('active');renderBookingSlots(b.dataset.bookDay)});
 };
 renderMonth();
 const chosen=bookingAvailability.find(x=>x.date===preferredDate&&x.slots.length);
 if(chosen)renderBookingSlots(chosen.date,preferredTime);
 else if(firstOpen)$('#bookingSlots').innerHTML='<p class="booking-hint">Choose an available date on the calendar to see that day’s times.</p>';
 else $('#bookingSlots').innerHTML='<p class="booking-hint">This teacher has no open times in the next 60 days.</p>';
}
function renderBookingSlots(date,preferredTime=''){
 const day=bookingAvailability.find(x=>x.date===date),wrap=$('#bookingSlots');$('#bookDate').value='';$('#bookTime').value='';$('#bookingSubmit').disabled=true;$('#bookingSelection').textContent='No time selected yet.';
 wrap.innerHTML=day&&day.slots.length?day.slots.map(t=>`<button type="button" class="booking-slot ${preferredTime===t?'active':''}" data-book-slot="${esc(t)}">${esc(bookingLocalTime(date,t,day?.timezone))}</button>`).join(''):'<p class="booking-hint">No available times on this day.</p>';
 const choose=b=>{ $$('[data-book-slot]',wrap).forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#bookDate').value=date;$('#bookTime').value=b.dataset.bookSlot;$('#bookingSubmit').disabled=false;const d=new Date(date+'T12:00:00');$('#bookingSelection').innerHTML=`<b>${esc(bookingLocalTime(date,b.dataset.bookSlot,day?.timezone))}</b><span>Your local time • ${esc(learnerTimeZone())}</span>`};
 $$('[data-book-slot]',wrap).forEach(b=>b.onclick=()=>choose(b));const preferred=$(`[data-book-slot="${preferredTime}"]`,wrap);if(preferred)choose(preferred);
}
