function statusLabel(s){return ({draft:'Draft',submitted:'Under review',changes_requested:'Changes requested',approved:'Approved',rejected:'Not approved'})[s]||s}
async function openApplicationDashboard(existing){let a=existing;try{if(!a||!a.id)a=await loadMyApplication()}catch{return applicationLogin()}const locked=['submitted','approved'].includes(a.status),score=a.profileScore||0;modal(`<div class="application-dashboard"><div class="application-status-head"><div><span class="eyebrow">APPLICATION ${esc(a.id||'')}</span><h2>${esc(statusLabel(a.status))}</h2><p>${a.status==='submitted'?'Your application is with iSpeak Confidence for review.':a.status==='approved'?'Your application is approved. Your teacher portal is active.':a.status==='changes_requested'?'Please update the requested items and submit again.':'Build a complete professional teacher profile, then submit it for review.'}</p>${a.reviewNote?`<div class="review-note"><b>Review note</b><p>${esc(a.reviewNote)}</p></div>`:''}</div><div class="profile-score"><b>${score}%</b><span>Profile ready</span></div></div><div class="application-tabs"><button class="active" data-app-tab="profile">Profile</button><button data-app-tab="media">Photo & video</button><button data-app-tab="background">Background</button><button data-app-tab="availability">Availability</button><button data-app-tab="review">Review</button></div><div id="applicationTabBody"></div></div>`);const renderTab=t=>{const b=$('#applicationTabBody');if(t==='profile')b.innerHTML=applicationProfileForm(a,locked);if(t==='media')b.innerHTML=applicationMediaForm(a,locked);if(t==='background')b.innerHTML=applicationBackgroundForm(a,locked);if(t==='availability')b.innerHTML=applicationAvailabilityForm(a,locked);if(t==='review')b.innerHTML=applicationReviewView(a,locked);bindApplicationActions(a,locked,t)};$$('[data-app-tab]',$('#modalBody')).forEach(x=>x.onclick=()=>{$$('[data-app-tab]',$('#modalBody')).forEach(y=>y.classList.toggle('active',y===x));renderTab(x.dataset.appTab)});renderTab('profile')}
function applicationProfileForm(a,l){const opts=APPLICATION_LANGUAGES.map(x=>`<label class="app-check"><input type="checkbox" data-teach-lang value="${x}" ${(a.teachingLanguages||[]).includes(x)?'checked':''} ${l?'disabled':''}>${x}</label>`).join('');return `<div class="application-section"><h3>1. Your teacher profile</h3><div class="two-col"><label>First name <span class="required-mark">Required</span><input id="taFirst" required value="${esc(a.firstName||'')}" ${l?'disabled':''}></label><label>Last name <span class="required-mark">Required</span><input id="taLast" required value="${esc(a.lastName||'')}" ${l?'disabled':''}></label><label>Public teacher name <span class="required-mark">Required</span><input id="taPublic" required value="${esc(a.publicName||'')}" placeholder="e.g. Jessica" ${l?'disabled':''}></label><label>Country <span class="required-mark">Required</span><input id="taCountry" required value="${esc(a.country||'')}" ${l?'disabled':''}></label><label>Phone <span class="required-mark">Required</span><input id="taPhone" required value="${esc(a.phone||'')}" ${l?'disabled':''}></label><label>Timezone <span class="required-mark">Required</span><input id="taTimezone" required value="${esc(a.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Phnom_Penh')}" ${l?'disabled':''}></label></div><h4>What can you teach?</h4><div class="app-check-grid">${opts}</div><label>Languages you speak <span class="required-mark">Required</span><input id="taSpoken" required value="${esc((a.spokenLanguages||[]).join(', '))}" placeholder="English, Khmer, Chinese" ${l?'disabled':''}></label><label>Profile headline <span class="required-mark">Required</span><input id="taHeadline" required maxlength="140" value="${esc(a.headline||'')}" placeholder="Experienced Khmer teacher focused on confident conversation" ${l?'disabled':''}></label><label>About you <span class="required-mark">Required</span><textarea id="taAbout" required rows="7" ${l?'disabled':''} placeholder="Tell students who you are, how you teach, and how you can help them. Aim for at least 160 characters.">${esc(a.about||'')}</textarea></label><div class="teacher-declarations"><label>Age group <span class="required-mark">Required</span><select id="taAgeGroup" ${l?'disabled':''}><option value="">Select age group</option><option value="15-17" ${a.ageGroup==='15-17'?'selected':''}>15–17</option><option value="18+" ${a.ageGroup==='18+'?'selected':''}>18 or older</option></select></label><label id="taGuardianWrap" style="${a.ageGroup==='15-17'?'':'display:none'}"><input id="taGuardianConsent" type="checkbox" ${a.guardianConsent?'checked':''} ${l?'disabled':''}> If I am 15–17, I confirm a parent or legal guardian has approved my application and online teaching work.</label><label><input id="taEquipment" type="checkbox" ${a.equipmentConfirmed?'checked':''} ${l?'disabled':''}> I have a suitable computer/device, camera and microphone for online lessons.</label><label><input id="taInternet" type="checkbox" ${a.internetConfirmed?'checked':''} ${l?'disabled':''}> I have a reliable internet connection for live classes.</label><label><input id="taAgreement" type="checkbox" ${a.agreementAccepted?'checked':''} ${l?'disabled':''}> I agree to iSpeak Confidence teacher rules, including protecting student contact and payment information.</label></div>${!l?'<button id="saveTeacherApplication" class="primary wide">Save profile</button>':''}</div>`}
function applicationMediaForm(a,l){return `<div class="application-section"><h3>2. Photo & introduction video</h3><p>Use a clear professional headshot and a friendly introduction video so students can understand your teaching style.</p><div class="media-preview-grid"><div>${a.photoUrl?`<img class="application-photo-preview" src="${a.photoUrl}" alt="Profile preview">`:'<div class="application-placeholder">📷<b>Profile photo</b></div>'}<label>Profile photo<input id="taPhoto" type="file" accept="image/jpeg,image/png,image/webp" ${l?'disabled':''}></label><small>JPG, PNG or WebP • maximum 4 MB</small></div><div>${a.videoUrl?`<video class="application-video-preview" src="${a.videoUrl}" controls></video>`:'<div class="application-placeholder">🎥<b>Intro video</b></div>'}<label>Introduction video<input id="taVideo" type="file" accept="video/mp4,video/webm" ${l?'disabled':''}></label><small>MP4 or WebM • maximum 55 MB</small></div></div>${!l?'<button id="saveTeacherApplication" class="primary wide">Upload & save</button>':''}</div>`}
function applicationBackgroundForm(a,l){return `<div class="application-section"><h3>3. Teaching background</h3><label>Teaching experience <span class="required-mark">Required</span><textarea id="taExperience" required rows="6" ${l?'disabled':''} placeholder="Describe your teaching experience, learner ages/levels, online teaching experience and results.">${esc(a.experience||'')}</textarea></label><label>Education <span class="required-mark">Required</span><textarea id="taEducation" required rows="4" ${l?'disabled':''} placeholder="Degrees, universities and relevant study.">${esc(a.education||'')}</textarea></label><label>Specialties <span class="required-mark">Required</span><input id="taSpecialties" required value="${esc((a.specialties||[]).join(', '))}" placeholder="Conversation, IELTS, Business English, Beginner Khmer" ${l?'disabled':''}></label><div>${(a.certificates||[]).map(c=>`<button type="button" class="certificate-file" data-app-file="${esc(c.url)}">📄 ${esc(c.name)}</button>`).join('')}</div><label>Certificates / qualifications <span class="required-mark">At least 1 required</span><input id="taCertificates" type="file" accept="application/pdf,image/jpeg,image/png" multiple ${l?'disabled':''}></label><small>Up to 5 files per save • PDF/JPG/PNG • 10 MB each</small><div class="info-panel"><b>Fixed iSpeak teacher rate</b><p>All approved tutors are paid <strong>$8 USD per completed 50-minute lesson</strong>. Students are charged the standard iSpeak lesson price of $13.</p></div>${!l?'<button id="saveTeacherApplication" class="primary wide">Save background</button>':''}</div>`}
function applicationAvailabilityForm(a,l){const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'],times=['08:00','09:00','10:00','11:00','12:00','13:00','14:00','15:00','16:00','17:00','18:00','19:00','20:00','21:00'];return `<div class="application-section"><h3>4. Weekly availability</h3><p>Select the times you can reliably teach each week. Once approved, you can change these from your portal.</p><div class="availability-editor">${days.map((d,di)=>`<div class="availability-row"><b>${d}</b><div>${times.map(t=>`<label class="time-check"><input type="checkbox" data-ta-day="${di}" value="${t}" ${(a.availability?.[String(di)]||[]).includes(t)?'checked':''} ${l?'disabled':''}><span>${localTimeLabel(t)}</span></label>`).join('')}</div></div>`).join('')}</div>${!l?'<button id="saveTeacherApplication" class="primary wide">Save availability</button>':''}</div>`}
function applicationRequiredChecks(a){return [
 ['First name',Boolean(String(a.firstName||'').trim())],
 ['Last name',Boolean(String(a.lastName||'').trim())],
 ['Public teacher name',Boolean(String(a.publicName||'').trim())],
 ['Country',Boolean(String(a.country||'').trim())],
 ['Phone number',Boolean(String(a.phone||'').trim())],
 ['Valid timezone',Boolean(String(a.timezone||'').trim())],
 ['Teaching language',(a.teachingLanguages||[]).length>0],
 ['Languages spoken',(a.spokenLanguages||[]).length>0],
 ['Profile headline',String(a.headline||'').trim().length>=25],
 ['About section',String(a.about||'').trim().length>=160],
 ['Teaching experience',String(a.experience||'').trim().length>=100],
 ['Education',String(a.education||'').trim().length>=20],
 ['Specialties',(a.specialties||[]).length>0],
 ['Qualification / certificate',(a.certificates||[]).length>0],
 ['Professional photo',Boolean(a.photoUrl)],
 ['Introduction video',Boolean(a.videoUrl)],
 ['Weekly availability',Boolean(a.availability&&Object.values(a.availability).some(v=>Array.isArray(v)&&v.length))],
 
 ['Age eligibility',a.ageGroup==='18+'||a.ageGroup==='15-17'],
 ['Guardian consent for 15–17',a.ageGroup!=='15-17'||Boolean(a.guardianConsent)],
 ['Equipment ready',Boolean(a.equipmentConfirmed)],
 ['Reliable internet',Boolean(a.internetConfirmed)],
 ['Teacher rules accepted',Boolean(a.agreementAccepted)]
]}
function applicationReviewView(a,l){const checks=applicationRequiredChecks(a),missing=checks.filter(([,ok])=>!ok).map(([n])=>n),complete=!missing.length;return `<div class="application-section"><h3>5. Review & submit</h3><p class="application-required-note"><b>Every required item must be completed before submission.</b> ${complete?'Your application is complete and ready to send to iSpeak Confidence Admin.':`${missing.length} required item${missing.length===1?' is':'s are'} still incomplete.`}</p><div class="application-checklist">${checks.map(([n,ok])=>`<div class="${ok?'done':'missing'}"><span>${ok?'✓':'!'}</span><b>${esc(n)}</b></div>`).join('')}</div><div class="application-preview-card">${a.photoUrl?`<img src="${a.photoUrl}">`:''}<div><span class="eyebrow">PROFILE PREVIEW</span><h2>${esc(a.publicName||[a.firstName,a.lastName].filter(Boolean).join(' ')||'Your name')}</h2><h4>${esc(a.headline||'Your teaching headline')}</h4><p>${esc(a.about||'Your description will appear here.')}</p><small>${esc((a.teachingLanguages||[]).join(' • '))}</small></div></div>${a.status==='approved'?`<div class="success-panel"><b>✓ Approved teacher account</b><p>${a.identityVerified?'Identity status: verified by iSpeak Confidence.':'Identity status: pending/manual review.'}</p><button id="approvedTeacherDashboard" class="primary wide">Open teacher portal</button></div>`:a.status==='submitted'?'<div class="info-panel"><b>Application received by Admin</b><p>Your application is now under review and cannot be edited until iSpeak approves it or requests changes.</p></div>':`<div class="application-submit-panel">${missing.length?`<p><b>Complete these before submitting:</b> ${missing.map(esc).join(', ')}.</p>`:'<p><b>Ready to submit.</b> Your application will immediately appear in the Admin Portal under teacher applications.</p>'}<button id="submitTeacherApplication" class="primary wide" ${complete?'':'disabled'}>${complete?'Submit application for review':'Complete required items to submit'}</button></div>`}</div>`}
async function bindApplicationActions(a,l,tab){$$('[data-app-file]',$('#modalBody')).forEach(x=>x.onclick=()=>openProtectedApplicationFile(x.dataset.appFile,{token:appAuthToken()}));const approvedDash=$('#approvedTeacherDashboard');if(approvedDash)approvedDash.onclick=()=>openApprovedTeacherDashboard();const ageGroup=$('#taAgeGroup'),guardianWrap=$('#taGuardianWrap'),guardianConsent=$('#taGuardianConsent');if(ageGroup&&guardianWrap&&!l){const syncGuardian=()=>{guardianWrap.style.display=ageGroup.value==='15-17'?'':'none';if(ageGroup.value!=='15-17'&&guardianConsent)guardianConsent.checked=false};ageGroup.addEventListener('change',syncGuardian);syncGuardian()}const save=$('#saveTeacherApplication');if(save)save.onclick=async()=>{save.disabled=true;save.textContent='Saving…';try{const payload={};if(tab==='profile'){payload.firstName=$('#taFirst').value;payload.lastName=$('#taLast').value;payload.publicName=$('#taPublic').value;payload.country=$('#taCountry').value;payload.phone=$('#taPhone').value;payload.timezone=$('#taTimezone').value;payload.teachingLanguages=$$('[data-teach-lang]',$('#modalBody')).filter(x=>x.checked).map(x=>x.value);payload.spokenLanguages=$('#taSpoken').value.split(',').map(x=>x.trim()).filter(Boolean);payload.headline=$('#taHeadline').value;payload.about=$('#taAbout').value;payload.ageGroup=$('#taAgeGroup').value;payload.guardianConsent=$('#taAgeGroup').value==='15-17'&&$('#taGuardianConsent').checked;payload.equipmentConfirmed=$('#taEquipment').checked;payload.internetConfirmed=$('#taInternet').checked;payload.agreementAccepted=$('#taAgreement').checked}else if(tab==='media'){payload.photo=await fileAsData($('#taPhoto')?.files?.[0]);payload.video=await fileAsData($('#taVideo')?.files?.[0])}else if(tab==='background'){payload.experience=$('#taExperience').value;payload.education=$('#taEducation').value;payload.specialties=$('#taSpecialties').value.split(',').map(x=>x.trim()).filter(Boolean);payload.currency='USD';payload.newCertificates=[];for(const f of Array.from($('#taCertificates')?.files||[]).slice(0,5))payload.newCertificates.push(await fileAsData(f))}else if(tab==='availability'){payload.availability={};$$('[data-ta-day]',$('#modalBody')).forEach(x=>{if(x.checked)(payload.availability[x.dataset.taDay]||(payload.availability[x.dataset.taDay]=[])).push(x.value)})}const d=await apiJSON('/api/teacher-application/save',{method:'POST',headers:{Authorization:`Bearer ${appAuthToken()}`},body:JSON.stringify(payload)});toast('Application saved.');openApplicationDashboard(d.application)}catch(e){toast(e.message||'Could not save application.')}finally{if(save){save.disabled=false;save.textContent='Save'}}};const submit=$('#submitTeacherApplication');if(submit)submit.onclick=async()=>{try{await apiJSON('/api/teacher-application/submit',{method:'POST',headers:{Authorization:`Bearer ${appAuthToken()}`},body:'{}'});toast('Application submitted for review.');openApplicationDashboard()}catch(e){toast(e.message||'Please complete the required sections first.')}}}
async function teacherPortalData(){return apiJSON('/api/teacher-application/portal',{method:'POST',headers:{Authorization:`Bearer ${appAuthToken()}`},body:JSON.stringify({action:'dashboard'})})}
function teacherMoney(n){return `$${Number(n||0).toFixed(2)}`}
function forceTeacherPasswordChange(required=true){modal(`<div class="teacher-password-change"><span class="eyebrow">TEACHER ACCOUNT SECURITY</span><h2>${required?'Create your permanent password':'Change password'}</h2><p>${STRONG_PASSWORD_HELP}</p><label>New password<input id="teacherNewPassword" type="password" autocomplete="new-password"></label><label>Confirm password<input id="teacherNewPassword2" type="password" autocomplete="new-password"></label><button id="saveTeacherNewPassword" class="primary wide">Save password</button>${required?'':'<button id="cancelTeacherNewPassword" class="secondary wide">Cancel</button>'}</div>`);if($('#cancelTeacherNewPassword'))$('#cancelTeacherNewPassword').onclick=()=>openApprovedTeacherDashboard('overview');$('#saveTeacherNewPassword').onclick=async()=>{const p=$('#teacherNewPassword').value;if(!strongPasswordOkay(p))return toast(STRONG_PASSWORD_HELP);if(p!==$('#teacherNewPassword2').value)return toast('Passwords do not match.');try{await apiJSON('/api/teacher-application/portal',{method:'POST',headers:{Authorization:`Bearer ${appAuthToken()}`},body:JSON.stringify({action:'changePassword',password:p})});toast('Password updated.');openApprovedTeacherDashboard('overview')}catch(e){toast(e.message||'Could not update password.')}}}
async function openApprovedTeacherDashboard(tab='overview'){let data;try{data=await teacherPortalData()}catch(e){if(e.message?.toLowerCase().includes('login'))return teacherAccountLogin();return toast(e.message||'Could not open your teacher portal.')}if(data.mustChangePassword)return forceTeacherPasswordChange();const isOwner=['nathan','ounnoun'].includes(String(data.teacher||'').trim().toLowerCase());const tabs=[['overview','Dashboard'],['calendar','Calendar'],['schedule','Availability'],['classroom','Virtual Classroom'],['lessons','Lessons'],['students','Students'],['messages','Messages'],['academy','Teacher Academy'],['pricing','Lesson Rate'],['profile','Profile'],...(isOwner?[['admin','Admin']]:[])];modal(`<div class="teacher-portal"><div class="teacher-portal-head"><div><span class="eyebrow">ISPEAK TEACHER PORTAL</span><h2>${esc(data.teacher)}</h2><p>${data.active?'Your profile is active and can accept bookings.':'Your profile is currently paused by iSpeak Confidence.'}</p></div><div class="teacher-head-tools"><div class="teacher-account-badges"><span>${data.identityVerified?'✓ Identity checked':'Identity review pending'}</span><span>$8 teacher pay / completed 50-min lesson</span></div>${teacherFlagSwitcher()}</div></div><div class="teacher-portal-tabs">${tabs.map(([k,n])=>`<button data-portal-tab="${k}" class="${k===tab?'active':''}">${n}</button>`).join('')}</div><div id="teacherPortalBody"></div><div class="teacher-portal-footer"><button id="teacherPortalPassword" class="text-btn">Change password</button><button id="teacherPortalLogout" class="text-btn">Log out</button></div></div>`);const render=t=>{const b=$('#teacherPortalBody');$$('[data-portal-tab]',$('#modalBody')).forEach(x=>x.classList.toggle('active',x.dataset.portalTab===t));if(t==='overview')renderTeacherOverview(b,data);if(t==='calendar')renderTeacherCalendar(b,data);if(t==='schedule')renderTeacherSchedule(b,data);if(t==='classroom')renderTeacherClassroomCentre(b,data);if(t==='lessons')renderTeacherLessons(b,data);if(t==='students')renderTeacherStudents(b,data);if(t==='messages')renderTeacherMessages(b,data);if(t==='academy')renderTeacherAcademy(b,data);if(t==='pricing')renderTeacherPricing(b,data);if(t==='profile')renderTeacherProfileEditor(b,data);if(t==='admin'&&isOwner)renderNathanAdmin(b,data);applyTeacherUiLanguage($('#modalBody'))};$$('[data-portal-tab]',$('#modalBody')).forEach(x=>x.onclick=()=>render(x.dataset.portalTab));$('#teacherPortalPassword').onclick=()=>forceTeacherPasswordChange(false);$('#teacherPortalLogout').onclick=()=>{localStorage.removeItem('isc-teacher-application-token');toast('Teacher account logged out.');teacherAccountLogin()};bindTeacherFlagSwitcher(tab);applyTeacherUiLanguage($('#modalBody'));render(tab)}
function renderNathanAdmin(b,d){
 b.innerHTML=`<div class="nathan-admin-panel"><div class="portal-section-head"><div><span class="eyebrow">OWNER CONTROLS</span><h3>${esc(d.teacher)} Admin</h3><p>Admin access is tied to your approved Nathan/Ounnoun teacher login. No second admin password is required.</p></div></div><div class="admin-owner-grid"><button id="nathanOpenAdmin" class="primary">Open full Admin Portal</button><button id="nathanRefreshTeachers" class="secondary">Refresh teacher list</button></div><div id="nathanAdminBody" class="owner-message-area"><p class="empty-state">Loading teachers…</p></div><div class="support-admin-box"><h3>Student support chats</h3><div id="adminSupportThreads"><p class="empty-state">Loading support chats…</p></div></div></div>`;
 const loadTeachers=async()=>{const host=$('#nathanAdminBody');try{const x=await apiJSON('/api/owner-teacher-messages',{headers:{Authorization:`Bearer ${appAuthToken()}`}});host.innerHTML=`<div class="owner-teacher-list"><h3>Teachers</h3>${x.teachers.length?x.teachers.map(t=>`<article class="owner-teacher-card"><div><b>${esc(t.name)}</b><span>${esc(t.email)}</span><small>${Number(t.lessonsTaught||0)} completed 50-minute lesson${Number(t.lessonsTaught||0)===1?'':'s'}${t.liveBookingId?' · LIVE NOW':''}</small></div><div><button class="secondary" data-owner-message="${esc(t.id)}">Message</button>${t.liveBookingId?`<button class="classroom-launch" data-owner-observe="${esc(t.liveBookingId)}">Observe live class</button>`:'<button class="secondary" disabled>No live class</button>'}</div></article>`).join(''):'<p>No other approved teachers yet.</p>'}</div><div id="ownerTeacherChat"></div>`;$$('[data-owner-message]',host).forEach(btn=>btn.onclick=()=>openOwnerTeacherChat(x,btn.dataset.ownerMessage));$$('[data-owner-observe]',host).forEach(btn=>btn.onclick=async()=>{try{const a=await apiJSON('/api/owner-admin-token',{method:'POST',headers:{Authorization:`Bearer ${appAuthToken()}`},body:'{}'});openISpeakClassroom(btn.dataset.ownerObserve,'admin',a.adminToken)}catch(e){toast(e.message||'Could not open observation room.')}})}catch(e){host.innerHTML=`<p class="error">${esc(e.message||'Could not load teachers.')}</p>`}};
 const openOwnerTeacherChat=(x,id)=>{const t=x.teachers.find(q=>q.id===id),host=$('#ownerTeacherChat');if(!t||!host)return;const msgs=(x.messages||[]).filter(m=>m.toId===id||m.fromId===id);host.innerHTML=`<div class="owner-chat-panel"><h3>Message ${esc(t.name)}</h3><div class="owner-message-log">${msgs.slice(-50).map(m=>`<article><p>${esc(m.text)}</p><small>${new Date(m.createdAt).toLocaleString()}</small></article>`).join('')||'<p>No messages yet.</p>'}</div><label>Message<textarea id="ownerTeacherText" rows="4" placeholder="Message ${esc(t.name)}…"></textarea></label><button id="ownerSendTeacher" class="primary">Send message</button></div>`;$('#ownerSendTeacher').onclick=async()=>{const text=$('#ownerTeacherText').value.trim();if(!text)return;await apiJSON('/api/owner-teacher-messages',{method:'POST',headers:{Authorization:`Bearer ${appAuthToken()}`},body:JSON.stringify({teacherId:id,text})});toast('Message sent.');loadTeachers()}};
 $('#nathanOpenAdmin').onclick=()=>openOwnerAdminDashboard();$('#nathanRefreshTeachers').onclick=loadTeachers;loadTeachers();
 const loadSupport=async()=>{const host=$('#adminSupportThreads');if(!host)return;try{const x=await apiJSON('/api/admin-support-messages',{method:'POST',headers:{Authorization:`Bearer ${appAuthToken()}`},body:JSON.stringify({action:'list'})});host.innerHTML=x.threads?.length?x.threads.map(t=>`<button class="secondary wide" data-support-thread="${esc(t.studentEmail)}">${esc(t.studentEmail)} · ${t.messages.length} message${t.messages.length===1?'':'s'}</button>`).join(''):'<p class="empty-state">No student support messages yet.</p>';$$('[data-support-thread]',host).forEach(btn=>btn.onclick=()=>openAdminSupportThread(btn.dataset.supportThread,d.teacher))}catch(e){host.innerHTML=`<p class="empty-state">${esc(e.message||'Could not load support chats.')}</p>`}};loadSupport();
}
const TEACHER_ACADEMY_MODULES=[
['Professional tutor profile','Build a trustworthy tutor profile with a professional photo, clear headline, intro video and learner-focused bio.'],['Learner-needs discovery','Identify goals, level, interests, confidence barriers and practical communication needs.'],['First-lesson assessment','Run a supportive first lesson that accurately identifies speaking, vocabulary, grammar and pronunciation needs.'],['Measurable learning goals','Turn broad learner wishes into realistic measurable lesson and course goals.'],['Lesson planning','Plan purposeful 50-minute lessons with a clear outcome, staged practice and flexible timing.'],['Useful vocabulary','Teach high-value vocabulary in context and move learners toward independent use.'],['Communicative grammar','Teach grammar through meaning, examples, guided use and real communication rather than lectures.'],['Speaking development','Increase student talking time with open questions, role plays, information gaps and real-life tasks.'],['Pronunciation coaching','Teach intelligibility, sounds, stress, rhythm and practical correction without harming confidence.'],['Effective correction','Choose when and how to correct errors and help learners self-correct.'],['Professional presence','Use voice, pacing, encouragement, boundaries and preparation to create a strong lesson experience.'],['iSpeak Classroom tools','Use the classroom, chat, shared workspace and lesson resources professionally and safely.'],['Homework that works','Set focused homework that reinforces the lesson and can be checked efficiently.'],['Quizzes and mini-tests','Use short assessments to measure actual progress without teaching to the test.'],['Adapting in real time','Adjust difficulty, pace and activity when the learner is bored, confused, anxious or ahead of plan.'],['Safeguarding','Keep lessons professional, protect younger learners and follow iSpeak safety and conduct requirements.'],['Student messaging','Communicate clearly inside iSpeak, protect private information and keep booking/payment conversations on-platform.'],['Student retention','Build consistency through useful lessons, visible progress, reliable communication and realistic next steps.'],['Difficult situations','Handle lateness, no-shows, technical problems, complaints and inappropriate behaviour professionally.'],['Reflective practice','Review evidence from lessons, identify what worked, and choose specific improvements for future teaching.']];
function renderTeacherSchedule(b,d){const av=d.availability||{},names=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];b.innerHTML=`<div class="portal-section-head"><div><span class="eyebrow">AVAILABILITY</span><h3>Weekly teaching availability</h3><p>Set the times students may request. This is different from Calendar, which shows lessons that are already scheduled.</p></div></div><div class="availability-editor">${names.map((n,i)=>`<section><h4>${n}</h4><input data-av-day="${i}" value="${esc((av[String(i)]||[]).join(', '))}" placeholder="17:00, 18:00, 19:00"><small>24-hour times, separated by commas</small></section>`).join('')}</div><button id="saveTeacherAvailability" class="primary wide">Save availability</button>`;$('#saveTeacherAvailability').onclick=async()=>{const next={};$$('[data-av-day]',b).forEach(x=>next[x.dataset.avDay]=x.value.split(',').map(v=>v.trim()).filter(v=>/^([01]\d|2[0-3]):[0-5]\d$/.test(v)));try{await apiJSON('/api/teacher-application/portal',{method:'POST',headers:{Authorization:`Bearer ${appAuthToken()}`},body:JSON.stringify({action:'availability',availability:next})});toast('Availability saved.');openApprovedTeacherDashboard('schedule')}catch(e){toast(e.message)}}}
function classroomJoinMeta(x,role){if(!x||String(x.status||'')==='practice')return {open:true,text:'Practice room is available now.'};const iso=role==='teacher'?x.teacherClassroomOpensAt:x.studentClassroomOpensAt;if(!iso)return {open:true,text:role==='teacher'?'Teacher entry opens 15 minutes before class.':'Student entry opens 10 minutes before class.'};const ms=Date.parse(iso),open=Date.now()>=ms;const when=new Date(ms).toLocaleString([],{weekday:'short',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});return {open,text:open?(role==='teacher'?'Teacher classroom is open now.':'Student classroom is open now.'):`${role==='teacher'?'Teacher':'Student'} can join from ${when} (${role==='teacher'?'15':'10'} minutes before class).`}}
function classroomButtonMarkup(x,role,attr,label='Join classroom'){const m=classroomJoinMeta(x,role),id=x.id||x.bookingId||'';return `<button class="classroom-launch ${m.open?'':'locked-entry'}" ${attr}="${esc(id)}" ${m.open?'':'disabled'}>${m.open?'🎥':'🔒'} ${esc(m.open?label:(role==='teacher'?'Opens 15 min before':'Opens 10 min before'))}</button>`}
function teacherLessonCard(x,compact=false){const m=classroomJoinMeta(x,'teacher');return `<article class="portal-lesson-card"><div><b>${esc(x.name||x.studentName||'Student')} · ${esc(x.subject||'Private lesson')}</b><span>${esc(x.date||'')} ${esc(String(x.time||'').slice(0,5))}</span><small>${esc(x.status||'confirmed')} · ${esc(m.text)}</small></div><div><button class="secondary" data-manage-lesson="${esc(x.id)}">Manage</button>${x.id?classroomButtonMarkup(x,'teacher','data-join-teacher-class'):''}</div></article>`}
function openTeacherLesson(d,id){const x=(d.bookings||[]).find(v=>v.id===id);if(!x)return toast('Lesson not found.');const m=classroomJoinMeta(x,'teacher');modal(`<span class="eyebrow">LESSON</span><h2>${esc(x.name||'Student')}</h2><p>${esc(x.subject||'Private lesson')} · ${esc(x.date||'')} at ${esc(String(x.time||'').slice(0,5))}</p><div class="info-panel"><b>Status: ${esc(x.status||'confirmed')}</b><p>${esc(m.text)}</p></div>${classroomButtonMarkup(x,'teacher','id','Enter classroom').replace('id="'+esc(x.id)+'"','id="teacherLessonJoin"')}<button id="teacherLessonBack" class="secondary wide">Back to Lessons</button>`);const j=$('#teacherLessonJoin');if(j)j.onclick=()=>openISpeakClassroom(x.id,'teacher');$('#teacherLessonBack').onclick=()=>openApprovedTeacherDashboard('lessons')}
function renderTeacherLessons(b,d){const rows=(d.bookings||[]).slice().sort((a,z)=>bookingStartValue(z)-bookingStartValue(a));b.innerHTML=`<div class="portal-section-head"><div><span class="eyebrow">LESSONS</span><h3>All lessons</h3><p>Manage scheduled, completed, cancelled and pending-payment lessons.</p></div></div>${rows.length?rows.map(x=>teacherLessonCard(x)).join(''):'<p class="empty-state">No lessons yet.</p>'}`;$$('[data-manage-lesson]',b).forEach(x=>x.onclick=()=>openTeacherLesson(d,x.dataset.manageLesson));$$('[data-join-teacher-class]',b).forEach(x=>x.onclick=()=>openISpeakClassroom(x.dataset.joinTeacherClass,'teacher'))}
function openTeacherLesson(d,id){const x=(d.bookings||[]).find(v=>v.id===id);if(!x)return toast('Lesson not found.');const gate=classroomJoinMeta(x,'teacher');modal(`<span class="eyebrow">LESSON</span><h2>${esc(x.name||'Student')}</h2><p>${esc(x.subject||'Private lesson')} · ${esc(x.date||'')} at ${esc(String(x.time||'').slice(0,5))}</p><div class="info-panel"><b>Status: ${esc(x.status||'confirmed')}</b><p>${esc(gate.text)}</p></div>${classroomButtonMarkup(x,'teacher','id','Enter classroom').replace(`id="${esc(x.id)}"`,'id="teacherLessonJoin"')}<button id="teacherLessonBack" class="secondary wide">Back to Lessons</button>`);const join=$('#teacherLessonJoin');if(join&&!join.disabled)join.onclick=()=>openISpeakClassroom(x.id,'teacher');$('#teacherLessonBack').onclick=()=>openApprovedTeacherDashboard('lessons')}
function academyState(){try{return JSON.parse(localStorage.getItem('isc-teacher-academy-120h-v185')||'{}')}catch{return {}}}
function academyCertificateId(d){const key='isc-teacher-academy-certificate-id';let id=localStorage.getItem(key);if(!id){id=`ISC-TUTOR-${new Date().getFullYear()}-${(crypto.randomUUID?.()||Math.random().toString(36).slice(2)).replace(/-/g,'').slice(0,8).toUpperCase()}`;localStorage.setItem(key,id)}return id}
function teacherCertificateName(d){const st=academyState(),saved=String(st.certificateName||'').trim();return saved||String(d.teacher||'Teacher').trim()||'Teacher'}
function saveTeacherCertificateName(d,name){const clean=String(name||'').trim().replace(/\s+/g,' ').slice(0,100);if(clean.length<2)throw new Error('Enter the tutor name exactly as it should appear on the certificate.');const st=academyState();st.certificateName=clean;localStorage.setItem('isc-teacher-academy-120h-v185',JSON.stringify(st));return clean}
function teacherCertificatePreview(d,unlocked=false){const st=academyState(),name=teacherCertificateName(d),id=academyCertificateId(d),date=st.completedAt?new Date(st.completedAt).toLocaleDateString():new Date().toLocaleDateString();return `<div class="academy-certificate-preview academy-award-preview ${unlocked?'':'locked'}"><div class="pro-tutor-cert-preview"><div class="pro-cert-corner top-left"></div><div class="pro-cert-corner bottom-right"></div><div class="pro-cert-ribbon"><b>120</b><span>HOURS</span></div><div class="pro-cert-brand"><img src="assets/logo.png" alt="iSpeak Confidence"><div><b>iSpeak Confidence</b><small>Professional Tutor Training</small></div></div><span class="pro-cert-kicker">CERTIFICATE OF PROFESSIONAL ACHIEVEMENT</span><small class="pro-cert-certifies">THIS IS TO CERTIFY THAT</small><b class="pro-cert-name">${esc(name)}</b><p>has successfully completed the</p><strong>120-Hour Professional Tutor Course</strong><em>and demonstrated the knowledge, skills and professional standards required to teach online with confidence and excellence.</em><div class="pro-cert-credentials"><span>✓ 20 Professional Modules</span><span>✓ Applied Teaching Tasks</span><span>✓ Detailed 50-Minute Lesson Plan</span><span>✓ Final Assessment — 80%+ Pass Standard</span></div><div class="pro-cert-title">CERTIFIED PROFESSIONAL TUTOR</div><div class="certificate-meta"><span><small>DATE AWARDED</small><b>${esc(date)}</b></span><span><small>CERTIFICATE ID</small><b>${esc(id)}</b></span></div>${unlocked?'':'<div class="certificate-preview-stamp">PREVIEW — LOCKED UNTIL COMPLETION</div>'}</div></div>`}
function renderTeacherAcademy(b,d){const saved=academyState(),done=new Set(saved.done||[]),score=Number(saved.score||0),plan=String(saved.plan||''),unlocked=done.size===TEACHER_ACADEMY_MODULES.length&&score>=80&&plan.length>=250,progress=Math.round(done.size/TEACHER_ACADEMY_MODULES.length*100);b.innerHTML=`<div class="portal-section-head"><div><span class="eyebrow">120-HOUR PROFESSIONAL TUTOR CERTIFICATION</span><h3>Teacher Academy</h3><p>Professional training for iSpeak tutors: 20 modules, applied teaching tasks, checkpoints, final assessment and lesson-plan assessment.</p></div></div><div class="academy-progress portal-kpis"><div><span>Modules complete</span><b>${done.size}/20</b><small>${progress}% complete</small></div><div><span>Training hours</span><b>${done.size*6}/120</b><small>6 hours per module</small></div><div><span>Final assessment</span><b>${score?score+'%':'Not taken'}</b><small>80% required</small></div></div><div class="academy-standard"><b>Professional certification standard</b><span>Complete every module and applied task, pass the final assessment at 80% or higher, and submit a satisfactory detailed 50-minute lesson plan.</span></div>${teacherCertificatePreview(d,unlocked)}${unlocked?`<div class="certificate-name-editor teacher-certificate-name-editor"><label>Name on certificate<input id="teacherCertificateName" maxlength="100" value="${esc(teacherCertificateName(d))}" placeholder="Type your full professional name"></label><button id="saveTeacherCertificateName" class="secondary">Update certificate name</button></div>`:''}<div class="academy-modules">${TEACHER_ACADEMY_MODULES.map((m,i)=>`<article class="${done.has(i)?'complete':''}"><span>${done.has(i)?'✓':i+1}</span><div><small>MODULE ${i+1} · 6 HOURS</small><h4>${esc(m[0])}</h4><p>${esc(m[1])}</p></div><button class="${done.has(i)?'secondary':'primary'}" data-academy-module="${i}">${done.has(i)?'Review module':'Open module →'}</button></article>`).join('')}</div><section class="academy-final"><h3>Final certification</h3><p>After all 20 modules, complete the 20-question applied assessment and detailed lesson-plan assignment.</p><button id="academyFinal" class="primary wide" ${done.size<20?'disabled':''}>Final assessment & lesson plan</button>${unlocked?'<button id="academyCertificate" class="secondary wide">🏆 Open & download certificate</button>':''}</section>`;$$('[data-academy-module]',b).forEach(btn=>btn.onclick=()=>openTeacherAcademyModule(d,Number(btn.dataset.academyModule)));$('#academyFinal').onclick=()=>openTeacherAcademyFinal(d);const saveName=$('#saveTeacherCertificateName');if(saveName)saveName.onclick=()=>{try{saveTeacherCertificateName(d,$('#teacherCertificateName').value);toast('Certificate name updated.');openApprovedTeacherDashboard('academy')}catch(e){toast(e.message)}};const cert=$('#academyCertificate');if(cert)cert.onclick=()=>openTeacherAcademyCertificate(d)}
function openTeacherAcademyModule(d,i){const m=TEACHER_ACADEMY_MODULES[i],st=academyState(),existing=String(st.tasks?.[i]||'');modal(`<div class="teacher-academy-module"><span class="eyebrow">MODULE ${i+1} · 6 HOURS</span><h2>${esc(m[0])}</h2><p>${esc(m[1])}</p><div class="academy-lesson-content"><b>Learn</b><p>Study the principle, identify what strong practice looks like, and connect it to a real iSpeak 50-minute lesson.</p><b>Apply</b><p>Describe a specific classroom example: what you would say or do, how the learner would respond, and how you would check that learning happened.</p><b>Reflect</b><p>Explain one mistake a tutor could make in this area and how you would avoid it.</p></div><div class="academy-checkpoint"><label>Applied task — minimum 250 characters<textarea id="academyTask" rows="10">${esc(existing)}</textarea></label><label>Checkpoint: What is the professional goal of this module?<select id="academyCheck"><option value="">Choose…</option><option value="1">Improve the learner's real learning experience safely and professionally</option><option value="0">Maximise teacher talking time</option><option value="0">Use one fixed lesson regardless of learner needs</option></select></label></div><button id="academyComplete" class="primary wide">Save & complete module</button>`);$('#academyComplete').onclick=()=>{const text=$('#academyTask').value.trim();if(text.length<250)return toast('Please complete the applied task with at least 250 characters.');if($('#academyCheck').value!=='1')return toast('Review the checkpoint and try again.');const x=academyState(),set=new Set(x.done||[]);set.add(i);x.done=[...set];x.tasks=x.tasks||{};x.tasks[i]=text;localStorage.setItem('isc-teacher-academy-120h-v185',JSON.stringify(x));toast('Module completed.');openApprovedTeacherDashboard('academy')}}
function openTeacherAcademyFinal(d){const st=academyState();modal(`<div class="academy-exam"><span class="eyebrow">FINAL ASSESSMENT</span><h2>Professional Tutor Certification</h2><p>Answer all 20 applied checkpoints and submit a detailed lesson plan. Pass mark: 80%.</p><div class="academy-final-questions">${TEACHER_ACADEMY_MODULES.map((m,i)=>`<label>${i+1}. Best professional response for ${esc(m[0])}?<select data-final-q><option value="">Choose…</option><option value="1">Adapt professionally to the learner while protecting learning quality and safety</option><option value="0">Ignore learner needs and follow one script</option><option value="0">Let the learner work alone without guidance</option></select></label>`).join('')}</div><div class="academy-rubric"><label>Detailed 50-minute lesson plan — minimum 250 characters<textarea id="academyLessonPlan" rows="12" placeholder="Include learner goal, outcome, stages, timing, speaking practice, correction, checks for learning and follow-up.">${esc(st.plan||'')}</textarea></label></div><button id="academySubmitFinal" class="primary wide">Submit final assessment</button></div>`);$('#academySubmitFinal').onclick=()=>{const qs=$$('[data-final-q]',$('#modalBody')),correct=qs.filter(x=>x.value==='1').length,score=Math.round(correct/20*100),plan=$('#academyLessonPlan').value.trim();if(qs.some(x=>!x.value))return toast('Answer all 20 questions.');if(plan.length<250)return toast('The lesson-plan assignment needs at least 250 characters.');const x=academyState();x.score=score;x.plan=plan;if(score>=80)x.completedAt=new Date().toISOString();localStorage.setItem('isc-teacher-academy-120h-v185',JSON.stringify(x));if(score>=80){toast('Passed — your professional certificate is unlocked. Add your preferred certificate name and download it from Teacher Academy.');openApprovedTeacherDashboard('academy')}else toast(`Score ${score}%. You need 80% to pass.`)}}
