 if(mode==='admin'){classroomPrejoin={id,mode,adminPin};$('#cancelISpeakClassroom').onclick=()=>{$('#modal').close();stopClassroomPrejoin()};$('#enterISpeakClassroom').onclick=async()=>{try{await classroomAPI(id,mode,adminPin,{action:'join',consent:false});stopClassroomPrejoin();renderISpeakClassroom(info,id,mode,adminPin,null)}catch(e){toast(e.message||'Could not join classroom.')}};return}
