 if(localStream){const localVideo=$('[data-room-video="local"]');if(localVideo){localVideo.srcObject=localStream;localVideo.play?.().catch(()=>{});localVideo.closest('.classroom-video-tile')?.classList.add('connected')}}if(practice&&!isAdmin){const remoteTile=$(`[data-video-tile="${remoteRole}"]`);remoteTile?.classList.add('practice-empty')}
