function ispeakDeviceId(){let id=localStorage.getItem('isc-device-id');if(!id){id='DEV-'+(crypto.randomUUID?crypto.randomUUID():Math.random().toString(36).slice(2)+Date.now().toString(36));localStorage.setItem('isc-device-id',id)}return id}
async function completeNewDeviceVerification(kind,email,onSuccess){modal(`<div class="device-verify-shell"><img src="assets/logo.png" alt="iSpeak Confidence"><span class="eyebrow">NEW DEVICE VERIFICATION</span><h2>Check your email</h2><p>We sent a 6-digit code to <b>${esc(email)}</b>. Enter it to trust this device.</p><label>Verification code<input id="deviceVerifyCode" inputmode="numeric" maxlength="6" autocomplete="one-time-code"></label><button id="deviceVerifySubmit" class="primary wide">Verify this device</button><button id="deviceVerifyBack" class="secondary wide">Back</button></div>`);$('#deviceVerifyBack').onclick=()=>kind==='teacher'?teacherAccountLogin():openAccountCentre('login');$('#deviceVerifySubmit').onclick=async()=>{try{const d=await apiJSON('/api/device-verification/confirm',{method:'POST',body:JSON.stringify({kind,email,deviceId:ispeakDeviceId(),code:$('#deviceVerifyCode').value})});await onSuccess(d)}catch(e){toast(e.message||'Verification failed.')}}}
function strongPasswordOkay(p){const s=String(p||''),letters=(s.match(/[A-Za-z]/g)||[]).length;return letters>=6&&/[A-Z]/.test(s)&&/\d/.test(s)}
const STRONG_PASSWORD_HELP='Use at least 6 letters, including 1 uppercase letter, and at least 1 number.';


/* V18.8.0 — complete email-code password recovery. */
function openPasswordReset(kind='student'){
 const teacher=kind==='teacher';
 modal(`<span class="eyebrow">PASSWORD RECOVERY</span><h2>${teacher?'Reset teacher password':'Reset your password'}</h2><p>Enter the email registered to your account. We will send a 6-digit code.</p><label>Email address<input id="resetEmail" type="email" autocomplete="email"></label><button id="resetSend" class="primary wide">Send verification code</button><button id="resetBack" class="secondary wide">Back</button><p id="resetMsg" class="muted"></p>`);
 $('#resetBack').onclick=()=>teacher?teacherAccountLogin():openAccountCentre('login');
 $('#resetSend').onclick=async()=>{const email=$('#resetEmail').value.trim().toLowerCase(),btn=$('#resetSend'),msg=$('#resetMsg');if(!email)return msg.textContent='Enter your email address.';btn.disabled=true;btn.textContent='Sending…';try{await apiJSON('/api/password-reset/request',{method:'POST',body:JSON.stringify({kind,email})});passwordResetCodeStep(kind,email)}catch(e){msg.textContent=e.message||'Could not send reset code.';btn.disabled=false;btn.textContent='Send verification code'}};
 setTimeout(()=>$('#resetEmail')?.focus(),50);
}
function passwordResetCodeStep(kind,email){
 const teacher=kind==='teacher';
 modal(`<span class="eyebrow">VERIFY YOUR EMAIL</span><h2>Check your email</h2><p>Enter the 6-digit code sent to <b>${esc(email)}</b>. It expires in 10 minutes.</p><label>Verification code<input id="resetCode" inputmode="numeric" autocomplete="one-time-code" maxlength="6"></label><label>New password<input id="resetNewPassword" type="password" autocomplete="new-password"></label><label>Confirm new password<input id="resetConfirmPassword" type="password" autocomplete="new-password"></label><button id="resetConfirm" class="primary wide">Change password</button><button id="resetResend" class="secondary wide">Send a new code</button><p id="resetMsg" class="muted"></p>`);
 $('#resetResend').onclick=()=>openPasswordReset(kind);$('#resetCode').oninput=e=>e.target.value=e.target.value.replace(/\D/g,'').slice(0,6);
 $('#resetConfirm').onclick=async()=>{const code=$('#resetCode').value,password=$('#resetNewPassword').value,confirm=$('#resetConfirmPassword').value,msg=$('#resetMsg'),btn=$('#resetConfirm');if(code.length!==6)return msg.textContent='Enter the 6-digit code.';if(password!==confirm)return msg.textContent='The two passwords do not match.';if(!strongPasswordOkay(password))return msg.textContent=STRONG_PASSWORD_HELP;btn.disabled=true;btn.textContent='Changing…';try{await apiJSON('/api/password-reset/confirm',{method:'POST',body:JSON.stringify({kind,email,code,password})});modal(`<span class="eyebrow">PASSWORD CHANGED</span><h2>Password changed</h2><p>Sign in with your new password.</p><button id="resetDone" class="primary wide">Back to log in</button>`);$('#resetDone').onclick=()=>teacher?teacherAccountLogin():openAccountCentre('login')}catch(e){msg.textContent=e.message||'Could not change password.';btn.disabled=false;btn.textContent='Change password'}};
}

function openAccountCentre(mode='login'){
 if(state.account?.token){modal(`<span class="eyebrow">MY ISPEAK ACCOUNT</span><h2>${esc(state.account.email)}</h2><p>Your progress is saved to this account and can be synchronized across devices.</p><p>Last sync: ${state.cloudSyncAt?new Date(state.cloudSyncAt).toLocaleString():'Not synced yet'}</p><button id="syncNow" class="primary wide">Sync now</button><button id="logoutAccount" class="secondary wide">Log out</button><button id="deleteAccount" class="danger wide">Delete account & cloud data</button>`);$('#syncNow').onclick=async()=>{try{await cloudSave();toast('Cloud progress synced');openAccountCentre()}catch(e){toast(e.message)}};$('#logoutAccount').onclick=()=>{state.account=null;localSave();render();$('#modal').close();toast('Logged out')};$('#deleteAccount').onclick=async()=>{if(!confirm('Permanently delete this iSpeak account and its cloud progress?'))return;try{await apiJSON('/api/account',{method:'DELETE',body:'{}'});state.account=null;localSave();render();$('#modal').close();toast('Account deleted')}catch(e){toast(e.message)}};return}
 const renderAuth=(kind)=>{
   const signup=kind==='register';
   modal(`<span class="eyebrow">ISPEAK CONFIDENCE ACCOUNT</span><h2>${signup?'Create your free account':'Welcome back'}</h2><p>${signup?'Save progress, certificates, bookings and learning history across your devices.':'Log in to continue from your saved progress.'}</p><div class="auth-title-row"><button id="authLoginTab" class="${signup?'':'active'}">Log In</button><button id="authSignupTab" class="${signup?'active':''}">Sign Up</button></div><label>Email address<input id="accountEmail" type="email" autocomplete="email" inputmode="email" placeholder="you@example.com"></label>${signup?`<label>Country of residence<select id="accountCountry"><option value="">Choose country</option>${['Cambodia','Ireland','China','United States','United Kingdom','Canada','Australia','France','Spain','Japan','United Arab Emirates','Saudi Arabia','Other'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Timezone<input id="accountTimezone" value="${esc(Intl.DateTimeFormat().resolvedOptions().timeZone||'')}" placeholder="Asia/Phnom_Penh"><small>Detected from this device. Change it if incorrect.</small></label>`:''}<label>Password<div class="password-row"><input id="accountPassword" type="password" autocomplete="${signup?'new-password':'current-password'}" placeholder="6+ letters, uppercase + number"><button id="showAccountPassword" class="password-toggle" type="button">Show</button></div></label><button id="accountSubmit" class="primary wide">${signup?'Create free account':'Log in'}</button>${signup?'':'<button id="studentForgotPassword" class="text-btn wide">Forgot password?</button>'}<div class="auth-switch"><span>${signup?'Already have an account?':'New to iSpeak?'}</span> <button id="authSwitch" type="button">${signup?'Log in':'Create account'}</button></div><p class="muted auth-note">${signup?'By creating an account you agree to the Terms of Use and Privacy Policy.':'Your local guest progress stays on this device until you sign in.'}</p>`);
   $('#authLoginTab').onclick=()=>renderAuth('login');$('#authSignupTab').onclick=()=>renderAuth('register');$('#authSwitch').onclick=()=>renderAuth(signup?'login':'register');
   if($('#studentForgotPassword'))$('#studentForgotPassword').onclick=()=>openPasswordReset('student');$('#showAccountPassword').onclick=()=>{const f=$('#accountPassword'),show=f.type==='password';f.type=show?'text':'password';$('#showAccountPassword').textContent=show?'Hide':'Show'};
   const go=async()=>{const email=$('#accountEmail').value.trim(),password=$('#accountPassword').value;if(!email)return toast('Enter your email address');if(signup&&!strongPasswordOkay(password))return toast(STRONG_PASSWORD_HELP);if(!signup&&!password)return toast('Enter your password');try{const d=await apiJSON('/api/account/'+kind,{method:'POST',body:JSON.stringify({email,password,deviceId:ispeakDeviceId(),country:signup?$('#accountCountry')?.value:'',timezone:signup?$('#accountTimezone')?.value:''})});if(d.verificationRequired)return completeNewDeviceVerification('student',email,async v=>{state.account={email:v.email,token:v.token};localSave();await cloudLoad();$('#modal').close();render();toast('Device verified — welcome back')});state.account={email:d.email,token:d.token};localSave();if(kind==='login')await cloudLoad();else await cloudSave();$('#modal').close();render();toast(kind==='login'?'Welcome back':'Account created — your progress is now saved')}catch(e){toast(e.message)}};
   $('#accountSubmit').onclick=go;$('#accountPassword').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();go()}};
   setTimeout(()=>$('#accountEmail')?.focus(),60);
 };
 renderAuth(mode==='register'?'register':'login');
}
