function localStoryText(h,v,ch,l){
 const en=storyParagraphsEN(h,v,ch),title=heroChapter(v,ch,l);
 if(l==='en') return en;
 const s=sceneFor(h,v,ch);
 const dict={
 zh:[`${s.a} ${h.name}没有忽略这个瞬间。${s.b} 起初只是一个小线索，却开始与城市周围更大的危险连接起来。`,`${v===1?'谜团才刚刚开始，每一个选择都会产生之后必须面对的后果。':'之前的冒险仍然影响着现在。第一卷中的决定正在改变接下来发生的一切。'} ${h.name}观察发生的变化，并意识到最安全的选择并不总是正确的选择。身边的人需要的是一个决定，而不是完美答案。`,`新的细节就在大家以为问题已经得到控制时出现。${h.name}谨慎地使用${h.power}，记住之前哪里出了问题，并拒绝再次犯同样的错误。`,`在《${title}》结束时，眼前的危险暂时被控制，但最后的线索指向了更远的地方。下一章会从这个结果直接继续，而不是重新开始故事。`],
 es:[`${s.a} ${h.name} no pasa por alto el momento. ${s.b} Lo que al principio parece una pista pequeña empieza a conectarse con un peligro mucho mayor alrededor de la ciudad.`,`${v===1?'El misterio todavía es nuevo y cada elección crea una consecuencia que importará más adelante.':'La aventura anterior todavía importa. Las decisiones del Volumen 1 ahora cambian lo que ocurre después.'} ${h.name} observa lo que ha cambiado y comprende que la opción más segura no siempre es la correcta. La gente cercana necesita una decisión, no una respuesta perfecta.`,`Aparece un nuevo detalle justo cuando el grupo cree tener el problema bajo control. ${h.name} usa ${h.power} con cuidado, recuerda lo que salió mal antes y se niega a repetir el mismo error.`,`Al final de «${title}», el peligro inmediato queda contenido, pero la última pista apunta hacia adelante. El siguiente capítulo comienza exactamente a partir de esta consecuencia, sin reiniciar la historia.`],
 fr:[`${s.a} ${h.name} ne laisse pas passer ce moment. ${s.b} Ce qui semblait n’être qu’un petit indice commence à se relier à un danger bien plus vaste autour de la ville.`,`${v===1?'Le mystère est encore récent et chaque choix crée une conséquence qui comptera plus tard.':'L’aventure précédente compte toujours. Les décisions du Volume 1 façonnent maintenant la suite.'} ${h.name} observe ce qui a changé et comprend que le choix le plus sûr n’est pas toujours le bon. Les personnes autour ont besoin d’une décision, pas d’une réponse parfaite.`,`Un nouveau détail apparaît au moment même où le groupe pense maîtriser la situation. ${h.name} utilise ${h.power} avec prudence, se souvient de l’erreur précédente et refuse de la répéter.`,`À la fin de « ${title} », le danger immédiat est contenu, mais le dernier indice pointe vers la suite. Le prochain chapitre reprend exactement cette conséquence au lieu de recommencer l’histoire.`],
 ja:[`${s.a} ${h.name}はその瞬間を見過ごさない。${s.b} 最初は小さな手がかりに見えたものが、街を包むもっと大きな危険へとつながり始める。`,`${v===1?'謎はまだ始まったばかりで、すべての選択が後の結果につながっていく。':'前の冒険は今も影響している。第1巻での決断が、これから起こることを形作っている。'} ${h.name}は変化を見つめ、いちばん安全な選択が必ずしも正しいとは限らないと気づく。周りの人たちが必要としているのは、完璧な答えではなく決断だ。`,`みんなが問題を抑えたと思った瞬間、新しい事実が現れる。${h.name}は${h.power}を慎重に使い、以前の失敗を思い出し、同じ間違いを繰り返さない。`,`「${title}」の終わりで目の前の危険はいったん収まる。しかし最後の手がかりは次へと続いている。次の章は物語をリセットせず、この結果からそのまま始まる。`],
 ar:[`${s.a} لا يتجاوز ${h.name} هذه اللحظة بسرعة. ${s.b} وما بدا في البداية دليلاً صغيراً يبدأ في الارتباط بخطر أكبر يحيط بالمدينة.`,`${v===1?'لا يزال الغموض في بدايته، وكل اختيار يصنع نتيجة سيكون لها أثر لاحقاً.':'لا تزال المغامرة السابقة مهمة، وقرارات الجزء الأول تشكل ما يحدث الآن.'} يراقب ${h.name} ما تغير ويدرك أن الخيار الأكثر أماناً ليس دائماً الخيار الصحيح. الناس من حوله يحتاجون إلى قرار، لا إلى إجابة مثالية.`,`تظهر معلومة جديدة تماماً عندما يظن الفريق أن المشكلة أصبحت تحت السيطرة. يستخدم ${h.name} قدرة ${h.power} بحذر، ويتذكر ما حدث خطأ من قبل ويرفض تكرار الخطأ نفسه.`,`في نهاية «${title}» تتم السيطرة على الخطر المباشر، لكن الدليل الأخير يشير إلى ما سيأتي. يبدأ الفصل التالي من نتيجة هذا القرار مباشرة بدلاً من إعادة القصة من البداية.`]
 };
 return dict[l]||en;
}
function storyParagraphsEN(h,v,ch){const s=sceneFor(h,v,ch),title=(v===1?ARC1:ARC2)[ch-1]||`Chapter ${ch}`,bridge=v===1?'The mystery is still new, and every choice creates a consequence that will matter later.':'The earlier adventure still matters. The decisions from Volume 1 now shape what happens next.';return [`${s.a} ${h.name} does not rush past the moment. ${s.b} What first looks like a small clue begins to connect with the larger danger surrounding the city.`,`${bridge} ${h.name} studies what has changed and notices that the safest choice is not always the right one. The people nearby are depending on a decision, not a perfect answer.`,`${s.c} A new detail appears just when the group thinks the problem is under control. ${h.name} uses ${h.power} carefully, remembering what went wrong before and refusing to repeat the same mistake.`,`By the end of “${title},” the immediate danger is contained, but the final clue points forward. The next chapter begins from this exact consequence rather than resetting the story.`]}
function heroesHome(){showLibraryPane('heroesLibraryPane');const l=heroLang(),c=HERO_LANGS[l],ui=STORY_I18N[l]||STORY_I18N.en,e=document.getElementById('heroesLibraryPane');if(!e)return;e.dir=l==='ar'?'rtl':'ltr';e.innerHTML=`<section class="heroes-lib story-series"><div class="heroes-top"><button class="library-back" data-library-home>${ui.library}</button><div><div class="eyebrow">${ui.series}</div><h1>${ui.choose}</h1><p>${ui.sub(c.chapters)}</p></div></div><div class="hero-grid">${ISPEAK_HEROES.map(h=>`<button class="hero-card story-hero-card" data-hero-shelf="${h.id}"><div class="story-cover-symbol">${h.name.slice(0,1)}</div><div class="hero-body"><span class="story-book-count">${ui.books}</span><h2>${h.name}</h2><p>${h.personality}</p><span class="power-chip">${h.power}</span><div class="hero-titles"><b>${localizedTitle(h,l,1)}</b><span>→</span><b>${localizedTitle(h,l,2)}</b></div></div></button>`).join('')}</div></section>`}
function heroShelf(id){const h=ISPEAK_HEROES.find(x=>x.id===id),l=heroLang(),c=HERO_LANGS[l],ui=STORY_I18N[l]||STORY_I18N.en,e=document.getElementById('heroesLibraryPane');if(!h||!e)return;showLibraryPane('heroesLibraryPane');e.dir=l==='ar'?'rtl':'ltr';e.innerHTML=`<section class="hero-shelf story-shelf"><button class="library-back" data-all-heroes>${ui.all}</button><div class="story-profile"><div class="story-cover-symbol large">${h.name.slice(0,1)}</div><div><div class="eyebrow">${h.power}</div><h1>${h.name}</h1><p>${h.personality}</p><strong>${h.hook}</strong></div></div><div class="series-order"><span>${ui.start}</span><i></i><span>${ui.continue}</span></div><div class="volume-grid">${[1,2].map(v=>heroVolume(h,l,c,v)).join('')}</div></section>`}
function heroVolume(h,l,c,v){const ui=STORY_I18N[l]||STORY_I18N.en,t=localizedTitle(h,l,v),p=heroProg(l,h.id,v),locked=l==='km';return`<button class="volume-card story-volume-card" ${locked?'data-khmer-locked':''} data-hero-read="${h.id}" data-volume="${v}" data-chapter="${Math.max(1,p||1)}"><div class="story-book-cover"><span class="vol-tag">${v===1?ui.v1:ui.v2}</span><small>${ui.series}</small><div class="story-cover-letter">${h.name.slice(0,1)}</div><b>${t}</b><em>${h.name} • ${ui.chapters(c.chapters)}</em></div><div class="volume-meta"><div><b>${locked?'Khmer edition awaiting approved text':p?ui.cont(p):ui.startReading}</b><small>${v===2?ui.continues:ui.begins}</small></div><span>→</span></div></button>`}
function heroRead(id,v,ch){trackAnalytics('story_open',{target:`${id}:v${v}`});const h=ISPEAK_HEROES.find(x=>x.id===id),l=heroLang(),c=HERO_LANGS[l],ui=STORY_I18N[l]||STORY_I18N.en;if(!h)return;if(l==='km')return khmerHeroNotice();ch=Math.min(Math.max(1,Number(ch)||1),c.chapters);saveHeroProg(l,id,v,ch);const t=localizedTitle(h,l,v),e=document.getElementById('heroesLibraryPane'),paras=localStoryText(h,v,ch,l);showLibraryPane('heroesLibraryPane');e.dir=l==='ar'?'rtl':'ltr';e.innerHTML=`<section class="story-reader"><div class="story-toolbar"><button data-hero-shelf="${id}">← ${h.name}</button><div><b>${t}</b><small>${ui.chapter(ch,c.chapters)}</small></div><select aria-label="${ui.chooseChapter}" data-story-chapter data-hero="${id}" data-volume="${v}">${Array.from({length:c.chapters},(_,i)=>`<option value="${i+1}" ${i+1===ch?'selected':''}>${l==='zh'?`第 ${i+1} 章`:l==='ja'?`第${i+1}章`:l==='ar'?`الفصل ${i+1}`:l==='es'?`Capítulo ${i+1}`:l==='fr'?`Chapitre ${i+1}`:`Chapter ${i+1}`}</option>`).join('')}</select></div><article class="story-page"><div class="chapter-title"><span>${l==='zh'?`第 ${ch} 章`:l==='ja'?`第${ch}章`:l==='ar'?`الفصل ${ch}`:l==='es'?`CAPÍTULO ${ch}`:l==='fr'?`CHAPITRE ${ch}`:`CHAPTER ${ch}`}</span><h1>${heroChapter(v,ch,l)}</h1></div>${paras.map((p,i)=>`<p${i===0?' class="story-lead"':''}>${p}</p>`).join('')}<div class="story-divider">◆</div><p class="story-next-tease">${ui.tease}</p></article><div class="manga-nav"><button ${ch===1?'disabled':''} data-story-nav data-hero="${id}" data-volume="${v}" data-chapter="${ch-1}">${ui.previous}</button><span>${ch} / ${c.chapters}</span><button ${ch===c.chapters?'disabled':''} data-story-nav data-hero="${id}" data-volume="${v}" data-chapter="${ch+1}">${ui.next}</button></div></section>`}
Object.assign(window,{heroesHome,heroShelf,heroRead});

/* V18.6.3 target-language-only story prose: prevents English leakage in non-English books. */
const HERO_LOCAL={
 zh:{jess:['有趣 • 自信 • 鼓励他人','共鸣之声','一段神秘广播把 Jess 引向一座语言能够改变现实的城市。'],jack:['认真 • 有策略 • 冷静幽默','思维地图','Jack Chen 发现一张会自己改变的地图，以及一座专门打乱所有计划的城市。'],pedro:['勇敢 • 精力充沛 • 冲动','勇气之火','城市灯光开始熄灭时，Pedro 的勇气点燃了一团奇异火焰。'],loulou:['温暖 • 聪明 • 善于社交','心灵连接','Loulou 能看见人与人之间隐藏的联系，直到有人开始切断它们。'],yuki:['害羞 • 观察敏锐 • 专注','专注之霜','一场无声风暴冻结城市时，Yuki 发现了所有人都忽略的细节。'],dariya:['冷静 • 守护他人 • 坚定','守护之盾','Dariya 被选中守护城市地下正在失去封印的古老大门。'],zyad:['好奇 • 大胆 • 爱冒险','风之疾行','Zyad 追随一阵只有他能感受到的风，来到本不该存在的遗迹。']},
 es:{jess:['Divertida • segura • alentadora','Voz de Resonancia','Una transmisión misteriosa llama a Jess hacia una ciudad donde las palabras pueden cambiar la realidad.'],jack:['Serio • estratégico • ingenioso','Mapa Mental','Jack Chen descubre un mapa que se redibuja solo y una ciudad creada para romper cualquier plan.'],pedro:['Valiente • enérgico • impulsivo','Llama del Valor','El valor de Pedro enciende una extraña llama justo cuando las luces de la ciudad empiezan a apagarse.'],loulou:['Cálida • inteligente • sociable','Vínculo del Corazón','Loulou puede sentir conexiones ocultas entre las personas, hasta que alguien empieza a cortarlas.'],yuki:['Tímida • observadora • muy concentrada','Escarcha de Enfoque','Yuki ve los detalles que todos ignoran cuando una tormenta silenciosa congela la ciudad.'],dariya:['Tranquila • protectora • decidida','Escudo Guardián','Dariya es elegida para proteger una antigua puerta cuyo sello se debilita bajo la ciudad.'],zyad:['Curioso • audaz • aventurero','Carrera del Viento','Zyad sigue un viento que nadie más puede sentir hasta unas ruinas que no deberían existir.']},
 fr:{jess:['Drôle • confiante • encourageante','Voix de Résonance','Une émission mystérieuse appelle Jess vers une ville où les mots peuvent changer la réalité.'],jack:['Sérieux • stratégique • subtilement drôle','Carte Mentale','Jack Chen découvre une carte qui se redessine seule et une ville conçue pour déjouer tous les plans.'],pedro:['Courageux • énergique • impulsif','Flamme du Courage','Le courage de Pedro allume une flamme étrange au moment où les lumières de la ville commencent à s’éteindre.'],loulou:['Chaleureuse • intelligente • sociable','Lien du Cœur','Loulou ressent les liens cachés entre les gens, jusqu’à ce que quelqu’un commence à les couper.'],yuki:['Timide • observatrice • très concentrée','Givre de Concentration','Yuki remarque les détails que tout le monde manque lorsqu’une tempête silencieuse fige la ville.'],dariya:['Calme • protectrice • déterminée','Bouclier Gardien','Dariya est choisie pour protéger une ancienne porte dont le sceau s’affaiblit sous la ville.'],zyad:['Curieux • audacieux • aventurier','Course du Vent','Zyad suit un vent que personne d’autre ne peut sentir vers des ruines qui ne devraient pas exister.']},
 ja:{jess:['楽しい • 自信がある • 励ます','共鳴の声','不思議な放送が Jess を、言葉が現実を変える街へと呼び出す。'],jack:['真面目 • 戦略的 • 静かなユーモア','マインドマップ','Jack Chen は自ら描き変わる地図と、あらゆる計画を崩すための街を発見する。'],pedro:['勇敢 • 活発 • 衝動的','勇気の炎','街の明かりが消え始める中、Pedro の勇気が不思議な炎を生み出す。'],loulou:['温かい • 賢い • 社交的','心のつながり','Loulou は人々の間にある見えないつながりを感じられるが、誰かがそれを切り始める。'],yuki:['控えめ • 観察力が高い • 集中力が強い','集中の霜','静かな嵐が街を止める中、Yuki は誰も気づかない細部を見つける。'],dariya:['冷静 • 守る • 意志が強い','守護の盾','Dariya は街の地下で封印が弱まる古い門を守る者に選ばれる。'],zyad:['好奇心旺盛 • 大胆 • 冒険好き','風の疾走','Zyad は誰にも感じられない風を追い、本来存在しないはずの遺跡へ向かう。']},
 ar:{jess:['مرحة • واثقة • مشجعة','صوت الرنين','يقود بث غامض Jess إلى مدينة تستطيع فيها الكلمات تغيير الواقع.'],jack:['جاد • استراتيجي • ذكي بهدوء','خريطة العقل','يكتشف Jack Chen خريطة تعيد رسم نفسها ومدينة صُممت لإفساد كل خطة.'],pedro:['شجاع • نشيط • مندفع','شعلة الشجاعة','تشتعل لدى Pedro شعلة غريبة في اللحظة التي تبدأ فيها أضواء المدينة بالانطفاء.'],loulou:['دافئة • ذكية • اجتماعية','رابط القلب','تستطيع Loulou الإحساس بالروابط الخفية بين الناس، إلى أن يبدأ شخص ما بقطعها.'],yuki:['هادئة • شديدة الملاحظة • مركزة','صقيع التركيز','تلاحظ Yuki التفاصيل التي يفوتها الجميع عندما تجمد عاصفة صامتة المدينة.'],dariya:['هادئة • حامية • مصممة','درع الحارس','يتم اختيار Dariya لحماية بوابة قديمة يضعف ختمها تحت المدينة.'],zyad:['فضولي • جريء • مغامر','اندفاعة الريح','يتبع Zyad ريحاً لا يستطيع أحد غيره الشعور بها نحو أطلال لا يفترض أن تكون موجودة.']}
};
function heroLocal(h,l){return HERO_LOCAL[l]?.[h.id]||[h.personality,h.power,h.hook]}
function localStoryText(h,v,ch,l){
 if(l==='en')return storyParagraphsEN(h,v,ch);
 const title=heroChapter(v,ch,l),loc=heroLocal(h,l),power=loc[1],phase=(ch-1)%4;
 const d={
 zh:{open:[`《${title}》开始时，${h.name}发现一个新的线索，而且它与之前发生的事情紧密相连。危险没有消失，只是换了一种形式。`,`${h.name}沿着线索前进，很快发现最明显的答案并不可信。每一步都让城市背后的谜团更加清晰。`,`团队以为已经找到解决办法，但一个新的变化迫使${h.name}重新考虑计划。之前的选择现在开始产生真正的后果。`,`就在局势最紧张的时候，${h.name}注意到一个别人忽略的细节。这个细节把当前的问题与更大的秘密连接起来。`],mid:`${h.name}没有急着行动，而是先观察周围的变化。最安全的选择不一定是正确的选择，身边的人需要一个决定，而不是完美答案。`,act:`当情况突然恶化时，${h.name}谨慎地使用${power}。这一次，${h.name}记住之前的错误，没有让力量代替判断。`,end:`章节结束时，眼前的危险暂时被控制，但最后的线索没有让故事结束。它直接指向下一章，也让之前的选择变得更加重要。`},
 es:{open:[`Al comenzar «${title}», ${h.name} encuentra una nueva pista conectada directamente con lo ocurrido antes. El peligro no ha desaparecido; simplemente ha cambiado de forma.`,`${h.name} sigue la pista y pronto descubre que la respuesta más evidente no es fiable. Cada paso revela un poco más del misterio que rodea la ciudad.`,`El equipo cree haber encontrado una solución, pero un cambio inesperado obliga a ${h.name} a replantear el plan. Las decisiones anteriores empiezan a tener consecuencias reales.`,`En el momento de mayor tensión, ${h.name} nota un detalle que los demás pasan por alto. Ese detalle conecta el problema actual con un secreto mucho mayor.`],mid:`${h.name} no actúa de inmediato. Primero observa qué ha cambiado. La opción más segura no siempre es la correcta, y las personas cercanas necesitan una decisión, no una respuesta perfecta.`,act:`Cuando la situación empeora de repente, ${h.name} usa ${power} con cuidado. Esta vez recuerda los errores anteriores y no deja que el poder sustituya al buen juicio.`,end:`Al terminar el capítulo, el peligro inmediato queda contenido, pero la última pista no cierra la historia. Señala directamente al siguiente capítulo y hace que las decisiones anteriores sean todavía más importantes.`},
 fr:{open:[`Au début de « ${title} », ${h.name} découvre un nouvel indice directement lié à ce qui s’est passé auparavant. Le danger n’a pas disparu ; il a simplement changé de forme.`,`${h.name} suit la piste et comprend vite que la réponse la plus évidente n’est pas fiable. Chaque étape révèle un peu plus le mystère qui entoure la ville.`,`L’équipe pense avoir trouvé une solution, mais un changement inattendu oblige ${h.name} à revoir le plan. Les décisions précédentes commencent à produire de vraies conséquences.`,`Au moment où la tension est la plus forte, ${h.name} remarque un détail que les autres ont manqué. Ce détail relie le problème actuel à un secret bien plus vaste.`],mid:`${h.name} n’agit pas tout de suite et observe d’abord ce qui a changé. Le choix le plus sûr n’est pas toujours le bon, et les personnes autour ont besoin d’une décision, pas d’une réponse parfaite.`,act:`Lorsque la situation se dégrade soudainement, ${h.name} utilise ${power} avec prudence. Cette fois, ${h.name} se souvient des erreurs précédentes et ne laisse pas le pouvoir remplacer le jugement.`,end:`À la fin du chapitre, le danger immédiat est maîtrisé, mais le dernier indice ne ferme pas l’histoire. Il mène directement au chapitre suivant et donne encore plus de poids aux choix précédents.`},
 ja:{open:[`「${title}」の始まりで、${h.name}は以前の出来事につながる新しい手がかりを見つける。危険は消えたのではなく、形を変えていた。`,`${h.name}は手がかりを追い、いちばん分かりやすい答えが信用できないと気づく。一歩進むたびに、街を包む謎が少しずつ見えてくる。`,`チームは解決策を見つけたと思うが、突然の変化で${h.name}は計画を考え直すことになる。これまでの選択が本当の結果を生み始める。`,`緊張が最も高まった時、${h.name}はほかの誰も気づかなかった細部を見つける。その細部が今の問題をもっと大きな秘密へつなげる。`],mid:`${h.name}はすぐには動かず、まず何が変わったのかを観察する。いちばん安全な選択が正しいとは限らない。周りの人たちが必要としているのは完璧な答えではなく、決断だ。`,act:`状況が急に悪化すると、${h.name}は${power}を慎重に使う。今回は以前の失敗を思い出し、力だけに判断を任せない。`,end:`章の終わりで目の前の危険はいったん抑えられる。しかし最後の手がかりは物語を終わらせず、そのまま次の章へと続き、これまでの選択をさらに重要なものにする。`},
 ar:{open:[`في بداية «${title}» يعثر ${h.name} على دليل جديد يرتبط مباشرة بما حدث من قبل. لم يختف الخطر، بل تغير شكله فقط.`,`يتبع ${h.name} الدليل ويكتشف سريعاً أن الإجابة الأكثر وضوحاً لا يمكن الوثوق بها. كل خطوة تكشف جزءاً أكبر من الغموض المحيط بالمدينة.`,`يعتقد الفريق أنه وجد حلاً، لكن تغيراً مفاجئاً يجبر ${h.name} على إعادة التفكير في الخطة. تبدأ القرارات السابقة بإظهار نتائج حقيقية.`,`في أكثر اللحظات توتراً يلاحظ ${h.name} تفصيلاً لم ينتبه إليه الآخرون. هذا التفصيل يربط المشكلة الحالية بسر أكبر بكثير.`],mid:`لا يتصرف ${h.name} فوراً، بل يراقب أولاً ما الذي تغير. الخيار الأكثر أماناً ليس دائماً الخيار الصحيح، والناس من حوله يحتاجون إلى قرار لا إلى إجابة مثالية.`,act:`عندما تسوء الأمور فجأة يستخدم ${h.name} قدرة ${power} بحذر. هذه المرة يتذكر الأخطاء السابقة ولا يسمح للقوة بأن تحل محل الحكم السليم.`,end:`في نهاية الفصل تتم السيطرة على الخطر المباشر، لكن الدليل الأخير لا ينهي القصة. إنه يقود مباشرة إلى الفصل التالي ويجعل القرارات السابقة أكثر أهمية.`}
 }[l];
 return [d.open[phase],d.mid,d.act,d.end];
}
function heroesHome(){showLibraryPane('heroesLibraryPane');const l=heroLang(),c=HERO_LANGS[l],ui=STORY_I18N[l]||STORY_I18N.en,e=document.getElementById('heroesLibraryPane');if(!e)return;e.dir=l==='ar'?'rtl':'ltr';e.innerHTML=`<section class="heroes-lib story-series"><div class="heroes-top"><button class="library-back" data-library-home>${ui.library}</button><div><div class="eyebrow">${ui.series}</div><h1>${ui.choose}</h1><p>${ui.sub(c.chapters)}</p></div></div><div class="hero-grid">${ISPEAK_HEROES.map(h=>{const loc=heroLocal(h,l);return `<button class="hero-card story-hero-card" data-hero-shelf="${h.id}"><div class="story-cover-symbol">${h.name.slice(0,1)}</div><div class="hero-body"><span class="story-book-count">${ui.books}</span><h2>${h.name}</h2><p>${loc[0]}</p><span class="power-chip">${loc[1]}</span><div class="hero-titles"><b>${localizedTitle(h,l,1)}</b><span>→</span><b>${localizedTitle(h,l,2)}</b></div></div></button>`}).join('')}</div></section>`}
function heroShelf(id){const h=ISPEAK_HEROES.find(x=>x.id===id),l=heroLang(),c=HERO_LANGS[l],ui=STORY_I18N[l]||STORY_I18N.en,e=document.getElementById('heroesLibraryPane');if(!h||!e)return;const loc=heroLocal(h,l);showLibraryPane('heroesLibraryPane');e.dir=l==='ar'?'rtl':'ltr';e.innerHTML=`<section class="hero-shelf story-shelf"><button class="library-back" data-all-heroes>${ui.all}</button><div class="story-profile"><div class="story-cover-symbol large">${h.name.slice(0,1)}</div><div><div class="eyebrow">${loc[1]}</div><h1>${h.name}</h1><p>${loc[0]}</p><strong>${loc[2]}</strong></div></div><div class="series-order"><span>${ui.start}</span><i></i><span>${ui.continue}</span></div><div class="volume-grid">${[1,2].map(v=>heroVolume(h,l,c,v)).join('')}</div></section>`}
